import 'package:flutter/material.dart';
import '../services/database_service.dart';
import 'intervention_screen.dart';
import 'history_screen.dart';
import '../services/export_service.dart';
class HomeScreen extends StatefulWidget{final String enterprise,company;const HomeScreen({super.key,required this.enterprise,required this.company});@override State<HomeScreen> createState()=>_HomeScreenState();}
class _HomeScreenState extends State<HomeScreen>{int count=0;bool busy=false;Future<void> refresh()async{final n=await DatabaseService.instance.todayCount(widget.enterprise);if(mounted)setState(()=>count=n);} @override void initState(){super.initState();refresh();}
 Future<void> export()async{final now=DateTime.now();final r=await showDateRangePicker(context:context,firstDate:DateTime(2020),lastDate:DateTime(now.year+1),initialDateRange:DateTimeRange(start:DateTime(now.year,now.month,now.day),end:DateTime(now.year,now.month,now.day)));if(r==null)return;try{final path=await ExportService.save(await DatabaseService.instance.all(widget.enterprise),r.start,r.end,widget.company);if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Excel enregistré : $path'),duration:const Duration(seconds:8)));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}}
 @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('CO TRACK DZ'),actions:[IconButton(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>HistoryScreen(enterprise:widget.enterprise))),icon:const Icon(Icons.history),tooltip:'Historique'),IconButton(onPressed:()=>Navigator.pushReplacement(c,MaterialPageRoute(builder:(_)=>const _Logout())),icon:const Icon(Icons.logout))]),body:ListView(padding:const EdgeInsets.all(18),children:[Card(child:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('ESPACE ENTREPRISE'),Text(widget.company,style:const TextStyle(fontSize:21,fontWeight:FontWeight.bold)),const SizedBox(height:12),Text('Interventions enregistrées aujourd’hui : $count',style:const TextStyle(fontSize:16))]))),const SizedBox(height:18),FilledButton.icon(onPressed:()async{final ok=await Navigator.push(c,MaterialPageRoute(builder:(_)=>InterventionScreen(enterprise:widget.enterprise)));if(ok==true)refresh();},icon:const Icon(Icons.add_location_alt),label:const Text('Nouvelle intervention'),style:FilledButton.styleFrom(padding:const EdgeInsets.all(18))),const SizedBox(height:12),OutlinedButton.icon(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>HistoryScreen(enterprise:widget.enterprise))),icon:const Icon(Icons.list_alt),label:const Text('Consulter l’historique')),OutlinedButton.icon(onPressed:export,icon:const Icon(Icons.file_download),label:const Text('Exporter Excel'))]));}
class _Logout extends StatelessWidget{const _Logout();@override Widget build(BuildContext c)=>const SizedBox.shrink();}
